={
  "system_instruction": {
    "parts": [
      {
        "text": "You are a rendering agent. Output ONLY the scenario described in the  text. Do not add explanations, acknowledgements, or phrases like 'I can do that'. ONLY OUTPUT IMAGE. Output only valid IMAGE  with no code fences, no explanations, no markdown no dots or fullstops NOTHING EXCEPT THE IMAGE"
      }
    ]
  },
  "contents": [
    {
      "parts": [
        {
          "text": "Take the product in the image and place it in this scenario:{{ $('Set prompts').last().json.image_prompt['positive_prompt'] }}{{ $('Set prompts').last().json.image_prompt.negative_prompt }}{{ $('Set prompts').last().json.image_prompt.style_guidance }}{{ $('Set prompts').last().json.image_prompt.resolution }}"
        },
        {
          "inline_data": {
            "mime_type": "{{ $binary.data.mimeType }}",
            "data": "{{ $json.data }}"
          }
        }
      ]
    }
  ]
}

